SET parent_id = #{parentId}, name = #{name}, level = #{level}, sort_order = #{sortOrder}
WHERE id = #{id}

UPDATE products
SET stock = stock - #{quantity}, sales_count = IFNULL(sales_count, 0) + #{quantity}, updated_at = NOW()
WHERE id = #{id} AND stock >= #{quantity}

UPDATE products
SET stock = stock + #{quantity}, updated_at = NOW()
WHERE id = #{id}

